mapper.select:
SELECT ail.* FROM (select t1.ID_, t1.PROC_INST_ID_, t1.ASSIGNEE_, t2.NAME_ PROCESS_NAME, t1.NAME_, t3.START_USER_ID_, t1.CREATE_TIME_ from act_ru_task t1, act_re_procdef t2, act_ru_execution t3 where t1.PROC_DEF_ID_ = t2.ID_ and t1.PROC_INST_ID_ = t3.PROC_INST_ID_ and t3.PARENT_ID_ is null) ail
and ail.PROC_INST_ID_ = #{process_instance_id}
and ail.PROCESS_NAME like concat('%', concat(#{process_name,jdbcType=VARCHAR}, '%'))
and ail.START_USER_ID_ like concat('%', concat(#{start_user_name,jdbcType=VARCHAR}, '%'))
and ail.CREATE_TIME_ > #{create_time_after}
and ail.CREATE_TIME_ < #{create_time_before}
and ail.ASSIGNEE_ = #{assignee}
order by ail.CREATE_TIME_ desc
